// Registry of curated champion kits. Champions without one use the tooltip-derived auto kit.
// In the browser the registry is filled from ./all.ts (generated by scripts/gen-kit-index.ts);
// in Node, src/node/kits.ts loads every file in ./champions directly.

import type { ChampionData } from '../engine/data-types.ts';
import type { ChampionKit } from '../engine/kit-types.ts';
import { autoKit } from '../engine/autokit.ts';
import { CURATED } from './all.ts';

type KitSource = ChampionKit | ((c: ChampionData) => ChampionKit);

const registry = new Map<string, KitSource>(Object.entries(CURATED));
const cache = new Map<string, ChampionKit>();

export function registerKit(id: string, kit: KitSource) {
  registry.set(id, kit);
  cache.delete(id);
}

export function getKit(champ: ChampionData): ChampionKit {
  let kit = cache.get(champ.id);
  if (!kit) {
    const curated = registry.get(champ.id);
    kit = curated ? (typeof curated === 'function' ? curated(champ) : curated) : autoKit(champ);
    cache.set(champ.id, kit);
  }
  return kit;
}

export function curatedChampionIds(): string[] {
  return [...registry.keys()];
}
